def tambah_stok(db, sku, n):
    db.execute(
        "INSERT INTO stok (sku, jumlah) VALUES (?, ?) "
        "ON CONFLICT (sku) DO UPDATE SET jumlah = stok.jumlah + EXCLUDED.jumlah",
        (sku, n),
    )

