import sqlite3

def baru():
    c = sqlite3.connect(":memory:")
    c.execute("CREATE TABLE stok (sku TEXT PRIMARY KEY, jumlah INTEGER NOT NULL)")
    return c

def jumlah(c, sku):
    r = c.execute("SELECT jumlah FROM stok WHERE sku = ?", (sku,)).fetchone()
    return r[0] if r else None

def jalankan(*langkah):
    c = baru()
    for sku, n in langkah:
        tambah_stok(c, sku, n)
    return c

